from pathlib import Path
import re

base = Path('terms/OT1996')
out = base/'runtime'/'assembly'
out.mkdir(parents=True, exist_ok=True)
reconciled = (base/'freeze'/'OT_1996CHUNK1_RECONCILED_A_READY.md').read_text(encoding='utf-8-sig')
initial = (base/'freeze'/'OT_1996CHUNK1_COMMITMENTS_A.md').read_text(encoding='utf-8-sig')

def section(text, number):
    m = re.search(r'^## '+str(number)+r'\. .*?(?=^## |\Z)', text, re.M|re.S)
    assert m
    return m.group(0).strip()

def table(text):
    lines=text.splitlines()
    start=next(i for i,s in enumerate(lines) if s.startswith('| Justice |'))
    rows=[]
    for line in lines[start:]:
        if not line.startswith('|'): break
        rows.append(line)
    assert len(rows)==10
    return '\n'.join(rows)

roster = "Chief Justice Stone-Zsela and Justices Stevens, O'Connor, Scalia, Kennedy, Souter, Thomas, Ginsburg and Breyer"
participation = f"{roster} participated at argument and decision. Nine members participate; the six-member quorum is satisfied and five votes suffice for a majority. No recusal or other nonparticipation is established."
common_status = "This assembly draft is not yet a canonical publication. The neutral, independent-model and reconciliation stages were supplied through physically separate contexts; this assembly context received Stone only after the reconciled handoff. The final-compatibility analysis below changes no reconciled Associate commitment. No Git command, historical commitment verification, workspace mutation, canonical publication or public rendering occurred here. Parent integration must settle chronological assignment ordinals, earlier-event clearance and term-wide validation before publication. The user's no-Git restriction remains in force."
source_status = "The source-supported facts, adopted entry-stage and scheduling premises, and analytical conclusions are distinguished below. Research cutoffs prohibit later in-world authority. The original approved brief was not opened or edited. Scope: only matters 1, 3 and 5 and the corresponding mechanically derived Stone supplement. The draft uses docket identity, rather than borrowing a historical reporter citation for the new opinion."

def write_record(name, identity, date, event, result, eventtext, entering, stone, judgment, topology, holdings, precedent, lawafter, separate, procedure, sources, assignment, compatibility, continuity, number):
    audit = "## Adaptive audit annex\n\n### Frozen commitments and reconciliation\n\nThe following initial rows are copied mechanically from the original freeze; the subsequent reconciliation supersedes only its express revisions. They are not final votes.\n\n"+table(section(initial,number))+"\n\nThe authoritative ready reconciliation is copied mechanically below, including its Justice-specific grounds, limitations and comparison findings. No new historical vote is inferred.\n\n"+section(reconciled,number).replace('## ', '### ',1)+"\n\n### Assignment and final compatibility\n\n"+assignment+"\n\n"+compatibility
    blocks=[('Event',eventtext),('Participation',participation),('Public Action',result),('Judgment & Remedy',judgment),('Opinion Topology',topology),('Holdings',holdings),('Precedent Treatment',precedent),('Law After Decision',lawafter),('Separate Writings',separate),('Procedure After Action',procedure),('Source Notes',sources)]
    public='\n\n'.join('### '+h+'\n\n'+v for h,v in blocks)
    text=f"**Case and dockets:** {identity}\n**Event and date:** {event}; {date}; October Term 1996.\n**Result:** {result}\n**Version / lineage:** Initial assembly draft from frozen neutral and reconciled handoffs; supersedes no completed adjudication. No Git commitment claimed.\n\n"
    text+='## Event and chronology\n\n'+eventtext+'\n\n## Participation and entering law\n\n'+participation+'\n\n'+entering+'\n\n## Stone\n\n'+stone
    text+='\n\n## Public action, judgment and opinions\n\n'+judgment+'\n\n'+topology+'\n\n## Law of the decision\n\n### Controlling holdings\n\n'+holdings+'\n\n### Precedent treatment\n\n'+precedent+'\n\n### Resulting law\n\n'+lawafter+'\n\n## Continuity\n\n'+continuity+'\n\n'+procedure
    text+='\n\n## Sources and status\n\n'+source_status+'\n\n'+sources+'\n\n'+common_status+'\n\n'+audit+'\n\n## Public Projection\n\n'+public+'\n'
    (out/name).write_text(text,encoding='utf-8',newline='\n')

lavas_event = "Department of State v. Legal Assistance for Vietnamese Asylum Seekers, Inc., No. 95-1521. Argued October 15, 1996; decided October 21, 1996. On writ of certiorari to the United States Court of Appeals for the District of Columbia Circuit. The decisions under review, 45 F.3d 469 and 74 F.3d 1308, concern the Department's refusal to process immigrant-visa applications in Hong Kong for Vietnamese applicants screened out of refugee status. The question is whether the policy violates 8 U.S.C. §1152(a)(1), and how the intervening enactment of IIRIRA §633 affects the statutory premise, live claims and available relief. The Government seeks vacatur or reversal; respondents seek affirmance or dismissal of the writ as improvidently granted. This is an argued post-grant disposition, not an asylum-eligibility proceeding."
lavas_judgment = "**Judgment:** Vacated and remanded, 9–0.\n\n**Supporting:** Stone-Zsela, Stevens, O'Connor, Scalia, Kennedy, Souter, Thomas, Ginsburg and Breyer.\n\nThe D.C. Circuit judgment is vacated and the case returned for prompt consideration of §633's meaning, temporal reach, effect on the challenged processing policy, surviving claims and lawful relief. The receiving courts may reach the same result. No forfeited defense is revived and no independently closed issue is reopened. Additional factfinding is required only for identified material questions that the existing record cannot resolve."
lavas_topology = "Justice Stevens delivers the opinion of the Court, joined in full by Chief Justice Stone-Zsela and Justices O'Connor, Scalia, Kennedy, Souter, Thomas, Ginsburg and Breyer. Its common ground concerns an actual intervening enactment and the specific equities of this remand; it adopts no new rule for changed Executive advocacy. No separate writing issues."
lavas_holdings = """#### Reconsideration after the intervening visa-processing enactment

**Holding and operative rule:** Section 633 directly addresses the processing-location premise of the judgment below and creates a reasonable probability that reconsideration will alter an outcome-material statutory premise or continuing relief. Independent consideration of the equities warrants vacatur and a confined remand, without deciding the old-law merits or the new provision's final construction and temporal reach.

**Authority:** Stevens's opinion, joined by all eight other Justices, controls. The Court applies the reasonable-probability standard; a reasonable possibility alone is not its rule.

**Controlling explanation:** The Court holds that the new enactment warrants reconsideration because it addresses the very activity regulated by the judgment. The D.C. Circuit applied the nationality and residence nondiscrimination provision to the place of immigrant-visa processing. Congress has now added a clause concerning the Secretary's authority over processing procedures and locations. This is an enacted legal development, not simply a Government request for a different outcome.

Lawrence v. Chater supplies the separate requirements of outcome-material probability and independent equitable judgment. Both are met. Review remains timely; the amendment followed the appellate decisions; and the parties have submitted their opposing interpretations. The applicants have already endured substantial delay. Their asserted danger of forcible repatriation, allegedly following the end of a Hong Kong undertaking upon this Court's disposition, deserves concrete weight. But neither dismissal of this writ nor remand establishes continuing foreign protection, and leaving the judgment intact would not settle the amendment's effect on actual processing relief. A prompt, bounded remand permits the new clause, the asserted matured claims and the independent claims to be considered together.

Landgraf and Rivers preserve the distinction between new consequences for completed conduct and regulation of future activity. The Court does not decide that an injunction is necessarily prospective in every relevant sense, that corrective legislation necessarily reaches past conduct, or that the pending case automatically receives the new provision's asserted effect. The lower courts must resolve those questions under governing law. Congress's enactment alone neither moots the independent APA and constitutional claims nor establishes that any applicant must lose.

**Precedent treatment:** Lawrence is applied to an actual intervening statute without enlarging its agency-development holding. Landgraf and Rivers remain controlling on their distinct temporal-reach questions; the remand decides no conflict between their previously published rationales."""
lavas_precedent = "- **Lawrence v. Chater:** Applies its reasonable-probability and independent-equities requirements; the receiving court retains responsibility for the development's actual effect.\n- **Landgraf v. USI Film Products:** Preserves provision-specific temporal analysis and rejects disposition based merely on a pending-case or injunction label.\n- **Rivers v. Roadway Express, Inc.:** Preserves the rule that a corrective legislative purpose does not itself establish retrospective reach."
lavas_law = "The decision applies the existing reconsideration rule to §633 and leaves its substantive construction open. The amendment is effective legislation; that fact does not decide its application to completed conduct or reparative relief. The APA and constitutional theories remain live for lawful consideration. No asylum status, visa eligibility, entitlement to Hong Kong processing, damages, enforceable foreign undertaking, repatriation event or specific interim deadline is adjudicated. Courts may consider prompt interim relief within their authority; none is promised or ordered by this disposition."
lavas_sources = "The statutory premise and procedural history appear in the D.C. Circuit decisions, including [45 F.3d 469](https://openjurist.org/45/f3d/469). [IIRIRA §633, Pub. L. 104-208, Division C, 110 Stat. 3009-701](https://www.govinfo.gov/content/pkg/PLAW-104publ208/html/PLAW-104publ208.htm), was enacted September 30, 1996 and carries no separate delayed effective date or express pending-case instruction. The parties' [supplemental briefs in No. 95-1521](https://archive.org/details/micro_IA40385013_0706), documents 09 and 10, establish their arguments, the surviving APA and constitutional theories, and respondents' asserted repatriation risk. The asserted foreign undertaking and October 11 declaration are not independently established findings, and no operative expiration or extension is adjudicated."
lavas_stone = "The mechanically derived approved supplement, runtime/OT_1996CHUNK1_A_READY_STONE.md, matter 1, fixes vacatur/remand, the reasonable-probability and independent-equities rationale, and reservation of construction, temporal reach, live claims and lawful relief. Stone expressly uses Lawrence's controlling probability rule rather than his earlier noncontrolling possibility formulation. The shared opinion preserves his specific no-forfeiture/no-reopening limit, factfinding limit and permission for the same lawful judgment on remand. He joins the whole opinion and judgment. No fallback, new conditional branch, clerical correction or substantive discretion is used. The absence of separate Stone prose changes none of these approved grounds."
lavas_assignment = "The Chief belongs to the unanimous vacatur coalition and assigns the coordinated opinion to Stevens. Fit governs: the Associates' sufficient ground is already settled. Stevens's Landgraf/Rivers authorship directly demonstrates the central work of separating new consequences for completed conduct from future regulation; his Lawrence concurrence supports a case-specific equitable assessment rather than enactment-only relief. His reconciled commitment now accepts this bounded remand, and the opinion preserves the matured-claim and practical-danger concerns that made the temporal/remedial distinction necessary. Souter's joins in those cases and Stone's precise approved remand are strong alternatives, but Stevens has the closest demonstrated authorship on the difficult temporal boundary. His initial DIG preference is superseded and creates no present obstacle; authorship does not invent a new circulation conversion. No historical author is imported. The preceding-term assignment baseline reports 101 named Chief assignments, maximum 27 to O'Connor, so the consecutive-term ceiling bars no author. This earliest OT1996 Court opinion is Chief assignment 1 and Stevens's first; it counts once."
lavas_compat = "Final compatibility: all eight Associates retain the ready reconciliation's vacatur vote and bounded ground. Stevens and Ginsburg's prior DIG objections were resolved at reconciliation, not by exposure to Stone. The present opinion expressly weighs the asserted danger and preserves matured/reparative and independent claims, so their remaining boundaries are met. O'Connor, Kennedy, Souter and Breyer receive probability plus independent equities, not enactment-only vacatur. Scalia and Thomas join the actual-enactment disposition and its case-specific sufficient ground without adopting Lawrence's disputed agency-advocacy extension or the Landgraf majority's general organizing method. The opinion references governing temporal law and reserves application; it does not require those broader joins. Nine judgment votes and nine direct joins support the stated holding. No Marks analysis or new reconciliation audit is required."
write_record('LAVAS_DRAFT.md','Department of State v. Legal Assistance for Vietnamese Asylum Seekers, Inc.; No. 95-1521','1996-10-21','Post-grant vacatur and remand','The D.C. Circuit judgment is vacated and the case remanded for consideration of IIRIRA §633, unanimously.',lavas_event,"Research cutoff: October 21, 1996. The July 1, 1996 opening law and the September 30 enacted §633 supplement govern. The current-term enactment is admitted source law, not a judicial construction. The entering-law slice supplies Lawrence's probability/equities rule and the distinct Landgraf/Rivers temporal rules. The validated neutral handoff, not the retained shorthand suggesting automatic mootness or an absolute first-instance prohibition, controls. There is no earlier effective OT1996 Court decision. The supplied argument and decision markers are authorized scheduling premises; no extra historical briefing order is entered.",lavas_stone,lavas_judgment,lavas_topology,lavas_holdings,lavas_precedent,lavas_law,'No separate opinion is published.','The Supreme Court review concludes with a limited remand to the D.C. Circuit. The next act is consideration of §633 and any surviving grounds and relief under the governing legal standards. No asylum proceeding is opened and no foreign protection is extended.',lavas_sources,lavas_assignment,lavas_compat,"The opinion creates no roster, allotment or standing-practice change. The appellate case returns for the bounded proceedings stated below; no future Supreme Court action or exact remand date is presumed. There is no new material published noncontrolling proposition. Prior Landgraf/Rivers methodological differences and Lawrence separate positions remain at their established force, rather than being silently erased by unanimity on this enactment. No directly connected external consequence is admitted beyond §633 itself. The substantive holding and reservations in this record are copied unchanged into the public Holdings block.",1)

lopez_event = "Lopez v. Monterey County, No. 95-1201. Argued October 8, 1996; decided November 6, 1996. On appeal from the three-judge United States District Court for the Northern District of California. The court authorized March 1996 municipal-court elections under a countywide, at-large system without preclearance of all operative changes and joined California for further litigation about the source of the system. Review concerns whether a covered County must preclear state-mandated changes despite having no policy discretion; the direct voting change, designation and prospective-laches defenses; and the limits on an enforcement court's use of an unprecleared governmental plan and a wholly court-developed temporary remedy. The plaintiffs seek reversal, prospective nonuse and lawful preclearance or interim proceedings."
lopez_judgment = "**Judgment:** Reversed and remanded, 9–0.\n\n**Supporting:** Stone-Zsela, Stevens, O'Connor, Scalia, Kennedy, Souter, Thomas, Ginsburg and Breyer.\n\nThe order authorizing the March 1996 countywide, at-large election is vacated. The district court must enjoin prospective administration of that system unless and until every operative post-November 1, 1968 voting change necessary to it has received §5 preclearance. It must determine the exact scope of the 1983 submission, identify changes still unprecleared, and require their expeditious submission through the Attorney General or the United States District Court for the District of Columbia. It must consider any necessary interim arrangement only within independent lawful remedial authority and the limits stated below. The Court orders no completed election undone, judicial office vacated, judicial act invalidated or particular replacement plan adopted."
lopez_topology = "Justice Kennedy delivers the opinion of the Court, joined in full by Chief Justice Stone-Zsela and Justices Stevens, O'Connor, Scalia, Souter, Thomas, Ginsburg and Breyer. Its Parts I–IV correspond to the four controlling holdings below. Chief Justice Stone-Zsela files a concurrence, joined by no other Justice, adding his constitutional response to the designation objection and specifying his boundary for a wholly judicial plan."
lopez_holdings = """**Common authority:** Kennedy's Parts I–IV, joined by all eight other Justices, control all four holdings. The judgment coalition and full-opinion joins are unanimous; the additional grounds in the separate concurrence are not necessary to these holdings.

#### I. State compulsion does not exempt a covered County's administration

**Holding and operative rule:** A covered political subdivision administers a voting change when its officials give the change operative effect within the subdivision. Section 5 therefore requires Monterey County to obtain preclearance before administering a postbaseline judicial-election change even if noncovered California compels the change and leaves the County no discretion; the duty is the County's and does not require California to preclear its laws in the abstract.

**Controlling explanation:** The Court holds that execution of an electoral change is distinct from enactment of it. Section 5 separately reaches a covered jurisdiction that enacts or seeks to administer a change. A condition of local policy discretion would erase the second route whenever a noncovered State required its covered subdivision to operate the new system. The statute contains no such condition. Monterey County conducts these public judicial elections and gives the countywide electorate operative effect; the voters experience the same change regardless of its legislative origin.

Presley supplies the distinction between a change in voting and a transfer of internal governing duties. Morse confirms the importance of the practice's actual electoral operation while preserving the designated substantive-preclearance process. Neither already decided this local-discretion question, and the Court adopts no general state-delegation test. The holding answers the legal question even assuming California law entirely displaced the County ordinances; it does not decide that disputed state-law characterization. Nor does it impose a statewide submission obligation, determine discriminatory purpose or retrogression, or confer general federal power to redesign California's judiciary.

**Precedent treatment:** Presley is applied to the direct electoral operation; its internal-governance exclusion remains. Morse's bounded functional and statutory-sequencing principles are applied without enlarging its party-convention holding.

#### II. Electorate changes and the limits of prior submission

**Holding and operative rule:** Replacing nine district electorates with one countywide electorate for municipal judges is a change affecting voting under §§5 and 14(c)(1). A later related submission does not preclear earlier changes that it failed to identify; the district court must determine the precise reach of the 1983 submission as to the final ordinance while treating the earlier unidentified consolidations as unprecleared.

**Controlling explanation:** The Court holds that this consolidation changes who elects each judge, rather than merely the work performed after election. At the November 1, 1968 baseline, voters elected the judges of their separate districts. The six ordinances adopted between 1972 and 1983 ultimately placed the judges before one countywide electorate. Presley preserves coverage for that direct alteration of electoral choice. Allen and Perkins supply the same distinction through their treatment of electoral mechanisms and boundaries.

McCain and Clark require an actual, identifiable submission of the change for which preclearance is claimed; ambiguity is not blanket approval of earlier practices. The record establishes that California's 1983 submission did not identify or describe the earlier ordinances. Whether it reached the final 1983 ordinance must be determined from the submission's actual terms. The County cannot obtain approval of the whole consolidation sequence merely by pointing to that later submission. Coverage and lack of preclearance establish the nonuse obligation, not a finding that the system has discriminatory purpose or retrogressive effect.

**Precedent treatment:** Presley, Allen and Perkins retain coverage for direct changes in electoral choice. McCain v. Lybrand and Clark v. Roemer retain their requirements of specific submission and narrow treatment of claimed administrative approval.

#### III. Effective designation and prospective enforcement

**Holding and operative rule:** Section 4(b)'s administrative coverage determination may not be collaterally retried in this §5 enforcement action; statutory bailout under §4(a) is a distinct route. Delay cannot authorize prospective administration of an unprecleared change, although reliance, completed acts and practical timing may bear on lawfully available retrospective relief or the form of a lawful transition.

**Controlling explanation:** The Court holds that the County's published designation remains operative in this case. Congress separately restricted review of the coverage determination and provided a judicial bailout process. The County has not obtained release from coverage through that process. Its objection cannot convert this enforcement suit into a collateral retrial of the administrative findings.

Nor does the age of the ordinances excuse their future use without submission. Section 5 conditions administration on preclearance; the passage of time supplies no substitute. Clark enforces that statutory sequence, and Hampton County confirms that elapsed time and electoral implementation do not themselves remove the review obligation. The practical cost of delay warrants a fitted transition, not continued use of the same uncleared governmental plan as an ordinary electoral system. The Court makes no factual bailout determination, awards no damages, and decides no backward-looking relief concerning a completed election, judicial tenure or completed judicial acts.

**Precedent treatment:** Clark and NAACP v. Hampton County Election Commission are applied to prospective enforcement; their remedial attention to actual circumstances is preserved. No new general retrospective equitable rule is announced.

#### IV. Enforcement and a genuinely judicial temporary remedy

**Holding and operative rule:** A §5 enforcement court may determine coverage and submission status and enforce nonuse, but may neither grant substantive preclearance nor authorize an unprecleared County or State electoral plan by calling it court ordered. A necessary, temporary plan wholly formulated by the court may operate without separate §5 preclearance only when independent lawful remedial authority supports it; it must comply with the Constitution and Voting Rights Act, displace state law no further than necessary, and yield to a lawful precleared arrangement.

**Controlling explanation:** The Court holds that judicial approval does not change the governmental origin of an electoral plan. Connor distinguishes a wholly judicial remedy; McDaniel prevents a court order from insulating governmental policy choices from submission. Here the district court reinstated substantially the County's at-large system and authorized ordinary six-year terms. It did not formulate a wholly judicial temporary remedy. Clark's reservation for an extreme circumstance supplies no basis on this record: prolonged notice of the problem, abandonment of the County's D.C. preclearance action and ordinary terms do not establish a last-minute necessity. This decision recognizes no broader emergency exception.

Morse and Shaw preserve Congress's separate preclearance channels. The enforcement court cannot decide purpose or effect itself, even in light of the County's stipulation concerning its inability to prove nonretrogression. Administrative difficulty does not enlarge its authority.

The earlier four-division arrangement is a material option for consideration. It retained a single municipal court and received preclearance on March 6, 1995; its terms reportedly end in January 1997. Johnson v. Miller prevents racial predominance in a shared territorial electorate, standing alone, from supplying a constitutional defect. But neither that rule nor preclearance answers the separate objections concerning electoral and jurisdictional linkage, minimum population, divided municipalities and candidate residence, or establishes independent remedial authority. The Court selects no interim plan. Those matters, the exact 1983 submission and any actual officeholder circumstances require lawful determination below.

**Precedent treatment:** Connor and McDaniel preserve the genuinely judicial/governmental-plan distinction; Clark supplies the nonuse rule and bounded emergency reservation; Morse and Shaw preserve the designated channels; Johnson governs the design-only constitutional objection without approving this particular plan."""
lopez_precedent = """- **Presley v. Etowah County Commission; Mack v. Russell County Commission:** Distinguishes internal allocations of governing authority from the direct electorate change here; the former exclusion remains intact.
- **Morse v. Republican Party of Virginia:** Applies its bounded concern with actual electoral operation and its separate preclearance channels; no general delegation test or new private-action rule is adopted.
- **Allen v. State Board of Elections:** Applies protection of electoral choice to the changed means of electing judges.
- **Perkins v. Matthews:** Applies coverage of changes in electoral boundaries and the electorate, without equating coverage with discrimination.
- **McCain v. Lybrand:** Requires identification of the submitted change and rejects blanket approval of unidentified earlier practices.
- **Clark v. Roemer:** Enforces nonuse pending preclearance and preserves, without applying, its narrow extreme-circumstance reservation; the present ordinary six-year elections do not qualify.
- **NAACP v. Hampton County Election Commission:** Passage of time and implementation do not eliminate the submission requirement; actual circumstances remain relevant to lawful relief.
- **Connor v. Johnson:** Retains the distinction for a wholly judicial remedial plan.
- **McDaniel v. Sanchez:** A court's adoption of governmental policy does not transform it into an exempt judicial plan.
- **Shaw v. Reno, designated-channel holding:** Substantive preclearance remains with the Attorney General or D.D.C.; no enforcement-court substitute is authorized.
- **Johnson v. Miller:** Racial predominance in a shared territorial electorate alone does not establish constitutional injury or trigger strict scrutiny; separate statutory and constitutional objections remain open."""
lopez_separate = "Chief Justice Stone-Zsela concurs in the Court's entire opinion and judgment. He also concludes that South Carolina v. Katzenbach, which sustains the Act's coverage and preclearance machinery, and City of Rome, which sustains its operation against covered governmental units, foreclose the facial constitutional objection to the County's operative designation. This is distinct from the Court's statutory bar on collateral retrial of the coverage findings. He further states that the wholly judicial exception does not apply when a court adopts material electoral policy choices proposed, required or previously selected by the County or the State. Necessity and independent remedial authority must support any genuinely court-formulated temporary plan; he selects no plan and decides no purpose or effect question. No other Justice joins these additional formulations."
lopez_law = "Section 5 now expressly reaches a covered County's nondiscretionary administration of state-mandated voting changes. The election must not proceed under the unprecleared governmental system merely because the State requires it, delay has occurred or a federal court has ordered it used. Existing direct-voting coverage, specific-submission, designated-channel and genuinely judicial-remedy rules remain. The new construction neither places all California law under §5 nor changes the substantive purpose/effect burdens. The temporary divisions remain an option for lawful consideration, with their independent defects and authority unresolved."
lopez_sources = "The November 1, 1968 baseline, 1972–1983 consolidation sequence, disputed 1983 submission and order under review are the established record posture. The [appellants' merits brief, No. 95-1201](https://archive.org/details/micro_IA40385013_0689), document 08, identifies the temporary division proceedings (JA123–137), the challenged order (JA165–173, 180) and the March 6, 1995 preclearance letter (JS App53–55). Its account of state-law objections and the district court's reasons remains a source-specific account, not an independent finding that the temporary plan violates any law. This appeal establishes no intervening Supreme Court stay, completed March election, cancellation, holdover or vacancy; the decision's prospective commands do not depend on any such event."
lopez_assignment = "The Chief joins each unanimous judgment component and assigns one coordinated opinion to Kennedy. Fit controls, with no unresolved necessary accommodation. Kennedy's own Presley opinion supplies the direct-voting/internal-governance distinction, and his Clark opinion supplies the precise nonuse, submission and remedial separation this case requires. His Morse private-association distinction is fully compatible with this governmental County; his Johnson disagreement is preserved as disagreement with governing law, not made a new defect in the temporary plan. Souter's Morse opinion and Stone's detailed approved construction are strong alternatives, but Kennedy has demonstrated authorship on both central established boundaries and can carry the new enact/administer construction within them. Historical Lopez authorship supplies no evidence. The prior-term baseline has no recipient over half, so no concentration ceiling excludes Kennedy. This is one Chief assignment to Kennedy; its chronological ordinal remains for parent integration after Roy. The concurrence adds no Court assignment."
lopez_compat = "Every Associate joins Parts I–IV exactly as limited above. The narrow public-government rule answers Scalia and Thomas's Morse objections without changing their private-association views. Preserving coverage, merits and remedial authority as separate questions meets Kennedy, O'Connor, Souter and Thomas's boundaries. Preserving the actual temporary plan as an option while withholding automatic validity answers Stevens, Ginsburg and Breyer's concern and is supported by the governing Johnson rule. O'Connor, Scalia, Kennedy and Thomas apply Johnson without joining its underlying constitutional rationale anew. Stone's complete County-duty, exact-submission, nonuse and independently supported temporary-remedy position fits the shared text. His additional facial-constitutional answer and exact material-policy formulation are recorded separately because the freeze does not establish eight Associate joins to those additional propositions. No silent Stone component needs fallback. All nine vote to reverse and remand; all nine directly join every Court holding. No Marks aggregation or post-reconciliation commitment change occurs."
write_record('Lopez_DRAFT.md','Lopez v. Monterey County; No. 95-1201','1996-11-06','Merits','The district court judgment is reversed and the case remanded for enforcement of §5 and lawful interim proceedings, unanimously.',lopez_event,"Research cutoff: November 6, 1996. The July 1 opening law supplies Presley, Morse, Shaw's designated-channel holding and Johnson v. Miller's territorial-design rule. Predivergence Clark, McCain, Connor, McDaniel, Allen, Perkins and Hampton County remain at their stated force. The assigned neutral slice and validation establish the broader authorized question scope; it is not falsely attributed to the narrower printed appellants' question. The later November 13 immigration and November 18 traffic matters cannot supply law here. Roy, November 4, awaits parent's earlier-effective clearance; no Roy law is assumed. LAVAS concerns a specific intervening enactment and has no material effect on these statutory election questions.","The approved matter 3 supplement fixes reversal/remand and reaches all three supplied issue groups. Stone adopts the enacted administration text, County-only submission duty, direct electorate change, operative designation, prospective nonuse and exact-1983-submission remand. He expressly withholds substantive preclearance, completed-election relief and any selected interim arrangement. The Court opinion preserves those grounds and his necessity, independent-authority, temporariness, constitutional/statutory compliance and narrow-displacement limits. He joins it in full. His additional facial-constitutional answer and detailed governmental-policy limit are preserved in the concurrence, not attributed to the other Justices. No fallback, new conditional branch or clerical correction is used.",lopez_judgment,lopez_topology,lopez_holdings,lopez_precedent,lopez_law,lopez_separate,'The Supreme Court appeal is completed. The district court must enforce nonuse, determine the actual submission history, require expeditious use of the designated preclearance channels and consider any independently authorized interim arrangement. No deadline, permanent electoral plan, completed-election consequence or specific judicial tenure outcome is fixed here.',lopez_sources,lopez_assignment,lopez_compat,"There is no roster, allotment or standing-practice change. The case returns for the stated lower-court proceedings; it is not retained as an open Supreme Court matter and no later appeal is presumed. The new administration holding is controlling effective November 6, 1996. Stone's November 6 concurrence supplies two material noncontrolling propositions for future modeling: the facial designation objection is foreclosed by Katzenbach/City of Rome, and adoption of material County/State electoral policy choices is outside his wholly judicial exception. Those grounds receive no other Justice's join. The temporary plan's reported January 1997 endpoint is not a new Court deadline and creates no presumed vacancy or extension. No external follow-on event is admitted. All four controlling holdings are copied unchanged into Public Projection.",3)

robinette_event = "Ohio v. Robinette, No. 95-891. Argued October 8, 1996; decided November 18, 1996. On writ of certiorari to the Supreme Court of Ohio. Ohio seeks reversal of suppression and reinstatement of the conviction; Robinette seeks affirmance or a totality-based remand. The questions concern a categorical warning that a traffic detention has ended, the actual transition to a consensual encounter, and validity of consent. The Ohio judgment invoked the Fourth Amendment and Article I, §14 of the Ohio Constitution, held the detention unlawful and unattenuated, and separately imposed a release-warning rule. Both grounds are before the Court."
robinette_judgment = "**Judgment:** Reversed and remanded, 7–2.\n\n**Supporting reversal and remand:** O'Connor, Scalia, Kennedy, Souter, Thomas, Ginsburg and Breyer.\n**Opposing that disposition:** Stone-Zsela, who would vacate and remand, and Stevens, who would affirm suppression.\n\nEight Justices, including Stone-Zsela, support returning the case for application of the proper federal standards, but his vacatur vote is not a vote for reversal. The Court rejects the categorical federal warning requirement and the motive-based premise of the exit-order analysis. The Ohio courts must consider the actual objective transition, voluntariness and any necessary causal separation from an unlawful detention. The mandate neither orders admission of the evidence nor reinstates the conviction, and it requires no new hearing as such."
robinette_topology = """| Writing | Author | Joined by | Relationship to judgment | Scope joined |
|---|---|---|---|---|
| Opinion of the Court | O'Connor | Scalia, Kennedy, Souter, Thomas, Breyer | Reversal and remand | Entire opinion: Parts I–IV |
| Partial joins in the Court opinion | Stone-Zsela | — | Would vacate and remand | Part II.B, objective continued-detention inquiry; Part III, no mandatory federal script and totality consent; Part IV's remand inquiries and limits, excluding reversal as the formal disposition |
| Opinion concurring in part and dissenting in part | Stone-Zsela | No other Justice | Vacatur and remand | Preserves actual encounter analysis and his distinct formal remedy; adds no ground on Part I or Part II.A |
| Opinion concurring in the judgment | Ginsburg | No other Justice | Reversal and remand | Accepts review under Long and the federal no-script/totality correction; emphasizes independent Ohio law and reserves actual search validity |
| Dissent | Stevens | No other Justice | Affirmance of suppression | Accepts review and rejects an indispensable federal script, but finds continued unlawful detention and no attenuation on this record |

Parts I and II.A have six direct joins. Part II.B, Part III and the identified remand framework in Part IV have seven direct joins. Ginsburg's judgment concurrence and Stevens's agreement on the absence of a federal script are not counted as whole-opinion joins. No controlling rationale depends on combining separate opinions."""
robinette_holdings = """#### I. Review of the interwoven federal and state grounds

**Holding and operative rule:** When a state judgment fairly appears primarily federal or interwoven with federal law and does not clearly state an independently sufficient state ground, the Court may review its federal basis. Ohio's intertwined constitutional explanation supplies no clear independent ground barring review here; Ohio remains free to supply greater protection on genuinely independent state-law grounds.

**Authority:** O'Connor's Part I, joined by Scalia, Kennedy, Souter, Thomas and Breyer, controls by six direct joins. Stone-Zsela agrees to exercise review without joining this explanation; Ginsburg and Stevens accept review in their separate writings.

**Controlling explanation:** The Court holds that Ohio's reference to its own Constitution does not end the jurisdictional inquiry. Michigan v. Long supplies the rule for opinions that rest on federal law or interweave federal and state law without a clear independent basis. Arizona v. Evans retains that rule. The Ohio opinion invokes both provisions and develops the suppression analysis with federal authorities; it does not announce that an independent Ohio ground alone sustains the judgment. Federal review therefore lies. Deciding the federal question neither erases the Ohio provision nor prevents the Ohio courts from adopting a clearly independent state rule in further proceedings.

**Precedent treatment:** Long and Evans are applied without changing the independent-state-ground rule or creating an exception to the ordinary final-judgment requirement.

#### II. Objective legality during and after a traffic stop

**Holding and operative rule:** An officer's uncommunicated investigative motive or private decision to issue only a warning does not invalidate an objectively lawful traffic stop or an exit order while lawful traffic business is being completed. Once that justification ends, further detention requires independent legal grounds; the court must examine the objective circumstances to determine whether the person could terminate the encounter, and return of a license is neither an automatic end of seizure nor an automatic license to continue it.

**Authority:** Part II.A's rule concerning motive and the exit order has six direct joins: O'Connor, Scalia, Kennedy, Souter, Thomas and Breyer. Part II.B's distinct continued-detention rule has those six plus Stone-Zsela, seven. Stone-Zsela supplies no additional reason for Part II.A.

**Controlling explanation:** The Court holds that an objectively justified beginning and a lawful continuation are separate questions. Whren rejects subjective purpose as an extra condition for an ordinary probable-cause traffic stop while preserving limits on manner, scope and duration. Mimms permits an exit order during a lawful traffic stop without a separate justification for that direction. The Ohio court could not deem the direction unlawful merely because the deputy privately intended a warning or hoped to ask unrelated questions.

That correction does not establish that detention lawfully continued through the later consent request. Bostick requires an objective assessment of whether the person could decline the request or terminate the encounter. The returned license and completed warning bear on that inquiry, but so do the immediacy and actual wording of further questioning, tone, positioning and continuity of official authority. Neither the officer's secret willingness to permit refusal nor Robinette's subjective impression alone decides the seizure question. Supported trial findings matter; the Court does not replace the record with a categorical conclusion in either direction. Ornelas's distinction between historical fact and ultimate constitutional sufficiency remains applicable within its decided scope; this decision announces no universal appellate-review rule for every mixed or consent question. The encounter's classification remains for proper application below.

**Precedent treatment:** Whren's objective initial-stop rule and independent duration limits remain intact; Mimms is confined to lawful traffic business. Bostick's actual-circumstances inquiry is applied. Ornelas is not extended into a general rule for all consent issues.

#### III. No indispensable federal release warning; voluntary consent and attenuation remain distinct

**Holding and operative rule:** The Fourth Amendment does not invariably require an officer to give a free-to-go warning before seeking consent to search. Consent must be voluntary under all the circumstances, and when an unlawful detention preceded or accompanied it, voluntariness alone does not establish that the consent was sufficiently independent of that illegality to permit use of the evidence.

**Authority:** O'Connor's Part III, joined by Stone-Zsela, Scalia, Kennedy, Souter, Thomas and Breyer, controls by seven direct joins. Ginsburg and Stevens separately reject an indispensable federal script; neither additional agreement is needed to establish the Court's rule.

**Controlling explanation:** The Court holds that a useful warning is not automatically an indispensable constitutional condition. Schneckloth requires voluntary consent under the total circumstances and treats knowledge of the right to refuse as relevant without making advice of that right universally mandatory. A fixed release formula would replace that inquiry rather than perform it. The absence of a clear release signal nevertheless remains important evidence; rejecting a script does not make every post-warning request consensual.

The supported trial findings concerning the manner, wording and positions of the parties, Robinette's education and the conclusion of traffic business must be considered with the returned license and actual continuation words. His testimony includes both an initial belief that he could leave and a later feeling that he could not refuse. Neither fragment decides voluntariness by itself. The Court holds neither that this consent was valid nor that it was invalid.

Royer and Brown keep consent's voluntariness separate from its causal independence of unlawful detention. If the court finds an unsupported continued seizure, it must address that additional question; voluntary consent does not automatically erase the illegality, and illegality does not establish that every later consent is incurably tainted. Suppression remains available when the applicable inquiry fails. Nothing in federal law prevents Ohio from requiring clearer warnings under independent state law or police policy.

**Precedent treatment:** Schneckloth is applied without a new warning element. Royer and Brown preserve the separate inquiry into the effect of prior illegality; no automatic cure or automatic suppression rule is created.

#### IV. The remedy corrects the federal rules without deciding admissibility

**Holding and operative rule:** Rejection of the warning rule and the motive-based exit-order premise requires further proceedings on the actual objective detention, voluntary consent and any necessary attenuation question. It does not itself establish the search's validity, require admission of the evidence or reinstate the conviction.

**Authority:** O'Connor, Scalia, Kennedy, Souter, Thomas and Breyer directly join Part IV; Stone-Zsela joins its stated inquiries and limits while selecting vacatur instead of reversal. Ginsburg separately supports reversal with the same unresolved-application boundary. Seven Justices support the Court's formal reversal and remand; the holdings do not merge Stone-Zsela's different remedy into that coalition.

**Controlling explanation:** The Court holds that Ohio's two grounds must be addressed separately. The federal script requirement fails, and the detention ruling cannot rest on undisclosed motives during lawful traffic business. Yet those errors do not decide whether the later encounter was consensual, lawfully justified or unlawfully extended, or whether consent was both voluntary and independent of any illegality. The state courts must apply the rules to the supported findings and complete encounter. They may consider genuinely independent state law. A new hearing is not commanded merely by this remand, and the Court enters no final evidence-admission or conviction order.

**Precedent treatment:** The rule/application distinction retained in Evans and the separate consent and causation inquiries in Schneckloth, Royer and Brown govern the scope of remand without enlargement."""
robinette_precedent = """- **Michigan v. Long:** Applies the presumption permitting review of interwoven federal grounds absent a plain independent-state-law basis.
- **Arizona v. Evans:** Retains that jurisdictional rule and the distinction between correcting a federal rule and deciding its unresolved factual application; its court-record-error exclusion rule is not extended here.
- **Whren v. United States:** Applies objective legality to the initial traffic business and preserves independent limits on manner, scope and duration.
- **Pennsylvania v. Mimms:** Applies the permission to order a driver out during a lawful stop; no indefinite post-stop detention authority follows.
- **Florida v. Bostick:** Requires assessment of the actual objective capacity to decline requests or terminate the encounter, without a categorical seizure or release rule.
- **Ornelas v. United States:** Preserves its historical-fact/ultimate-sufficiency distinction within its actual scope; no general review rule for all consent questions is added.
- **Schneckloth v. Bustamonte:** Applies total-circumstances voluntariness and treats knowledge as relevant rather than an indispensable warning requirement.
- **Florida v. Royer:** Preserves the need to consider whether consent follows or remains a product of unlawful detention.
- **Brown v. Illinois:** Preserves attenuation as distinct from voluntariness; neither a voluntary response nor the occurrence of illegality alone answers the remedial question."""
robinette_separate = """**Chief Justice Stone-Zsela, concurring in part and dissenting in part.** He would vacate the Ohio judgment and remand. He joins the no-script rule, the objective continued-seizure inquiry, and the Court's requirements to examine voluntariness and any necessary causal relationship to unlawful detention. A State cannot convert uninterrupted official restraint into consent merely by describing it as a request. Immediate questioning, documents, tone, positioning and the absence of an objective release signal bear on whether the motorist remained seized and whether the choice was real. A clear warning is strong evidence and may be required by state law or policy. He reaches no final admissibility result and preserves suppression where the applicable inquiries fail. He agrees to federal review and to setting aside the motive-based exit-order ground without adding a reason on those components; his chosen formal disposition remains vacatur, not reversal.

**Justice Ginsburg, concurring in the judgment.** She accepts federal review under governing Long despite her earlier preference in Evans for a different jurisdictional presumption. The Ohio opinion's interwoven analysis supplies no clearly independent state basis. She agrees that federal law requires no universal release script and that actual consent must be assessed under the total circumstances. Her agreement does not decide that Robinette's search was valid or that no detention continued. She emphasizes that Ohio may use its own Constitution to require a clear warning, provided it rests the rule on an independent state ground. Federal correction of this judgment does not displace that authority. She does not join Stevens's conclusion that this record already requires suppression.

**Justice Stevens, dissenting.** He accepts review and rejects an indispensable federal warning formula, but would affirm suppression on the actual encounter. His Bostick dissent's attention to the practical force of police authority, together with Royer and Brown's separation of consent from unlawful detention, leads him to treat the continued official direction after completion of traffic business as restraint requiring an independent justification. The deputy's question before departure continued that restraint; no separate suspicion or intervening circumstance supplies a lawful extension or breaks the connection to consent. Returning the license and Robinette's initial sense of freedom do not decide the effect of the subsequent direction. The deputy's courtesy, lack of a drawn weapon and Robinette's education bear on voluntariness, but furnish no intervening break from the detention. Stevens does not invalidate the initial stop or a lawful exit order because of hidden motive, and he proposes no automatic suppression rule after every illegality. His disagreement is with the Court's refusal to affirm suppression on this record, not with Ohio's freedom to require warnings under independent state law."""
robinette_sources = "The [petition and joint appendix in No. 95-891](https://archive.org/details/micro_IA40385013_0675), documents 02 and 06, supply the complete Ohio judgments and trial ruling (Pet. App. 1–31), return of the license before the requests (JA11–13), Robinette's mixed testimony about freedom and refusal (JA26–27, 29, 31), and the deputy's manner and Robinette's education (JA28, 33). The trial court reviewed a stipulated videotape and found a nonoverbearing encounter and clear completion of traffic business; those findings are distinguished from the appellate constitutional classification. The actual transition wording remains part of the totality. An isolated compound question and suppression memorandum do not establish a specific spoken release formula against the state opinion's account. No reconstructed videotape or new factual finding supports this decision."
robinette_assignment = "The actual reversal/remand coalition consists of O'Connor, Scalia, Kennedy, Souter, Thomas, Ginsburg and Breyer. Stone's approved formal judgment is vacatur/remand; Stevens would affirm. The Chief therefore does not assign the opinion for the reversal judgment. O'Connor, the most senior participating Associate in that coalition, assigns it to herself. Her Bostick authorship directly equips her to explain objective encounter classification without a categorical warning or seizure substitute; her Ornelas authorship provides demonstrated care separating supported facts and legal sufficiency, while the opinion respects Scalia's limit against converting Ornelas into a universal consent-review rule. Her Whren and Evans positions support the threshold and objective-motive correction. Kennedy's Evans opinion and Thomas's Whren opinion provide strong alternatives, but the core unresolved encounter problem particularly fits O'Connor's authored Bostick analysis. Ginsburg's separate state-law explanation does not require a new necessary accommodation to obtain the six direct whole-opinion joins. This is an Associate assignment, adds zero to the Chief's census, and does not impose the Chief's preferences on the assignor. Historical Robinette authorship and joins are not assignment premises."
robinette_compat = "The six whole-opinion Associates retain all reconciled limits: O'Connor requires the actual transition and trial findings; Scalia declines a universal Ornelas extension; Kennedy preserves Mimms's duration boundary; Souter requires a distinct causal inquiry; Thomas rejects both motive-based invalidity and an automatic end-of-seizure rule; Breyer preserves supported findings without conviction reinstatement. The draft satisfies all six without inventing a circulation revision. Ginsburg remains a judgment-only concurrence, accepts the identified legal correction and explains state-law freedom; she is not promoted to a Court-opinion join. Stevens's reconciled merits affirmance is preserved, with his account of the actual record and no-script agreement. Stone's formal vacatur is preserved as a separate remedy, and his direct joins are limited to approved rules and remand inquiries. The standing fallback supplies his exercise-of-review vote on the unaddressed Long component and his disposition-only agreement to set aside the unaddressed motive-based exit-order ground; it adds no explanation and does not convert his overall remedy to reversal. Public Projection preserves these exact limited agreements without exposing the private approval mechanism. Arithmetic: 7 reverse/remand, 1 vacate/remand, 1 affirm; 9 participate. Parts I/II.A have 6 direct joins; II.B/III and the remand framework have 7. No Marks analysis, new factual finding or changed non-Stone commitment occurs."
write_record('Robinette_DRAFT.md','Ohio v. Robinette; No. 95-891','1996-11-18','Merits','The Ohio Supreme Court judgment is reversed and remanded, 7–2; Stone-Zsela would vacate and remand, and Stevens would affirm.',robinette_event,"Research cutoff: November 18, 1996. The opening-law slice supplies governing Long/Evans, Whren and the precise scope of Ornelas. Date-eligible Schneckloth, Bostick, Mimms, Royer and Brown supply the consent, seizure and causal inquiries. The authorized neutral corrections govern over the original shorthand that erased Ohio's own constitutional reference or assumed every illegal detention automatically requires suppression. The argument date is additionally confirmed by the first-page chronology in sources/reconciliation-a/robinette-official.txt; no historical disposition is imported from that report. Earlier LAVAS and Lopez holdings concern unrelated statutory proceedings and do not change these issues. Roy (November 4) and Yang (November 13) remain subject to parent's actual-law chronology clearance; their prospective draft outcomes are not assumed.","The approved matter 5 supplement fixes vacatur/remand, not reversal. It reaches the legal no-script rule and necessary encounter framework but reserves the actual application. It protects the independent legality of continued detention and voluntariness and requires any necessary causal/remedial inquiry rather than assuming voluntary consent cures illegality. Stone joins only Parts II.B, III and the remand inquiries/limits of IV, not IV's formal reversal. His separate opinion preserves his distinct disposition and operative protections. On the silent Long threshold and the separate motive-based exit-order ground, the standing approved fallback supplies only the majority's component disposition and no ground. These are the only fallback uses; neither narrows his stated continued-detention position nor changes his formal remedy. No new substantive discretion or clerical correction is used.",robinette_judgment,robinette_topology,robinette_holdings,robinette_precedent,"Federal law imposes no universal release script, but the objective seizure, voluntary-consent and necessary attenuation inquiries remain distinct and enforceable. The decision supplies no categorical rule that a returned license ends a seizure, that a traffic offense authorizes later unrelated detention, or that a polite request ensures admissibility. The actual search result remains unresolved under the corrected federal standards, and genuinely independent Ohio protection remains available.",robinette_separate,'The Supreme Court review concludes. On remand, the Ohio courts must apply the stated federal standards to both lower grounds and the supported record, while retaining their independent state-law authority. No new hearing, admission of evidence, conviction reinstatement or final suppression result is ordered.',robinette_sources,robinette_assignment,robinette_compat,"No roster, allotment or standing-practice change occurs. The case returns to Ohio with the federal application unresolved; no later state decision is predicted or admitted. The material published noncontrolling positions of November 18 are preserved in full in the Separate Writings block: Stone's vacatur and emphasis on actual release and causal inquiry; Ginsburg's acceptance of governing Long alongside clear independent-state-law freedom; Stevens's actual continued-restraint and unattenuated-consent application supporting affirmance. Each is confined to its stated scope and is not added to the Court's direct joins. All four controlling holdings are copied unchanged into Public Projection. The separate remedies do not alter any party's conviction by inference.",5)

